contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 amount, uint256 timestamp) public payable {

        // read-only call via public getter to establish precondition
        uint256 beforeBalance = address(c).balance;

        require(amount == 10 ether, "must send exactly 10 ether");
        require(address(this).balance >= amount, "insufficient balance");

        // drive time forward — block.timestamp is fixed per transaction; use it as is
        // set up prior state of pastBlockTime if needed via a first call? only one call allowed

        uint256 beforePastBlockTime = c.pastBlockTime();

        bool success;
        try c.fallback{value: amount}() {
            success = true;
        } catch {
            success = false;
        }

        uint256 afterBalance = address(c).balance;
        uint256 afterPastBlockTime = c.pastBlockTime();

        assert(
            (success == (block.timestamp > beforePastBlockTime)) &&
            (!success || afterPastBlockTime == block.timestamp) &&
            (success && (block.number % 15 == 0) ? afterBalance == 0 : true) &&
            (success && (block.number % 15 != 0) ? afterBalance == beforeBalance + amount : true)
        );
    }

    receive() external payable {}
}

