contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 amount, uint256 expectedOk) public payable {
        require(address(this).balance >= amount);
        require(amount == 10 ether || amount != 10 ether);
        require(expectedOk == 0 || expectedOk == 1);

        // Read the before-state through the public getter.
        uint256 beforePastBlockTime = c.pastBlockTime();
        uint256 beforeBalance = address(c).balance;

        // For the rule “if timestamp > pastBlockTime then success” to be meaningful,
        // the caller must be able to satisfy the timestamp precondition.
        // If pastBlockTime is already maximal, only the revert branch is possible.
        require(c.pastBlockTime() < type(uint256).max);

        // Make the deciding call.  The fallback requires exactly 10 ether, so
        // amount must be 10 ether; otherwise it reverts before reading timestamp.
        bool reverted;
        try c.fallback{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterPastBlockTime = c.pastBlockTime();
        uint256 afterBalance = address(c).balance;

        // General rule: with exactly 10 ether and a strictly larger timestamp than
        // the stored one, the call must complete, set pastBlockTime to the current
        // timestamp, and leave c's Ether balance increased by the sent amount
        // (unless the payout branch ran, which only sends Ether out but cannot touch
        // the stored timestamp).  With any other amount it must revert and leave
        // pastBlockTime and c's Ether balance unchanged.
        if (amount == 10 ether && c.pastBlockTime() < block.timestamp) {
            assert(
                !reverted &&
                afterPastBlockTime == block.timestamp &&
                afterBalance >= beforeBalance + amount - ((block.number % 15 == 0) ? beforeBalance + amount : 0)
            );
        } else {
            assert(
                reverted &&
                afterPastBlockTime == beforePastBlockTime &&
                afterBalance == beforeBalance
            );
        }
    }

    receive() external payable {}

    fallback() external payable {}
}

