            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterPastBlockTime = c.pastBlockTime();
        uint256 afterBalance = address(c).balance;

        if (amount == 10 ether && block.timestamp > beforePastBlockTime) {
            // The call should not revert; pastBlockTime should be updated to the
            // current block.timestamp. The balance either increases by amount
            // or resets to zero if the payout branch runs.
            assert(
                !reverted &&
                afterPastBlockTime == block.timestamp &&
                (afterBalance == beforeBalance + amount || afterBalance == 0)
            );
        } else {
            // The call must revert and leave state and balance unchanged.
            assert(
                reverted &&
                afterPastBlockTime == beforePastBlockTime &&
                afterBalance == beforeBalance
            );
        }
    }

    receive() external payable {}

    fallback() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 amount, uint256 forcedTimestamp) public payable {
        require(address(this).balance >= amount);

        // Bring pastBlockTime to a known value so we can control whether
        // the next fallback call hits the strict timestamp gate.
        uint256 start = block.timestamp + forcedTimestamp;
        if (c.pastBlockTime() != start) {
            if (start <= block.timestamp) {
                // Leave state as-is; the gate outcome is still determined by
                // comparing block.timestamp with the observed pastBlockTime.
            } else {
                c.fallback{value: 10 ether}();
            }
        }

        uint256 beforePastBlockTime = c.pastBlockTime();
        uint256 beforeBalance = address(c).balance;

        bool reverted;
        try c.fallback{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterPastBlockTime = c.pastBlockTime();
        uint256 afterBalance = address(c).balance;

        if (amount == 10 ether && block.timestamp > beforePastBlockTime) {
            assert(
                !reverted &&
                afterPastBlockTime == block.timestamp &&
                (afterBalance == beforeBalance + amount || afterBalance == 0)
            );
        } else {
            assert(
                reverted &&
                afterPastBlockTime == beforePastBlockTime &&
                afterBalance == beforeBalance
            );
        }
    }

    receive() external payable {}
}

