    }

    receive() external payable {}

    function run(uint256 amount, uint256 waitSeconds) public payable {
        require(amount == 10 ether, "amount must be exactly 10 ether");
        require(address(this).balance >= amount, "insufficient balance");

        // Ensure the initial state has a timestamp that can be strictly greater than
        // after waiting: first call is made after the constructor, so any fresh
        // pastBlockTime starts at 0.
        uint256 beforeTime = c.pastBlockTime();

        // Optionally wait (but this is a single transaction, so timestamp is fixed).
