        uint256 callTime = block.timestamp;
        bool reverted;
        try c.fallback{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (!reverted) {
            assert(c.pastBlockTime() == callTime);
        } else {
            assert(c.pastBlockTime() == beforeTime);
        }
    }
}

