            setupReverted = true;
        }
        require(!setupReverted);

        uint t0 = c.pastBlockTime();
        require(t0 >= block.timestamp - 1 seconds);

        // Decide the timestamp for the test call.
        uint testTime = time % 2 == 0 ? t0 + 1 : t0;

        c.pastBlockTime();
        uint balanceBefore = address(c).balance;
        uint myBalanceBefore = address(this).balance;

        bool reverted;
        try c{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (amount != 10 ether || testTime <= t0) {
            assert(reverted);
            assert(address(c).balance == balanceBefore);
            assert(address(this).balance == myBalanceBefore + amount);
        } else {
            assert(!reverted);
            assert(c.pastBlockTime() == testTime);
            if (block.number % 15 == 0) {
                assert(address(c).balance == 0);
                assert(address(this).balance == myBalanceBefore - amount + balanceBefore + amount);
            } else {
                assert(address(c).balance == balanceBefore + amount);
                assert(address(this).balance == myBalanceBefore - amount);
            }
        }
    }

    receive() external payable {}
}

