            }
        }

        uint256 beforeTime = c.pastBlockTime();
        bool reverted;
        try c.fallback{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterTime = c.pastBlockTime();

        if (!reverted) {
            assert(
                amount == 10 ether &&
                afterTime > beforeTime &&
                afterTime == block.timestamp
            );
        } else {
            assert(
                amount != 10 ether ||
                afterTime == beforeTime ||
                afterTime < block.timestamp
            );
        }
    }

    receive() external payable {}
}

