contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint amount, uint64 targetTimestamp) public payable {
        require(address(this).balance >= amount, "not enough balance");
        require(targetTimestamp > 0, "timestamp must be positive");

        uint oldPast = c.pastBlockTime();

        // If targetTimestamp is not already greater than the current pastBlockTime,
        // push pastBlockTime down below it by calling the fallback with exactly 10 ether
        // while block.timestamp is still <= targetTimestamp.  block.timestamp is
        // strictly greater than the current oldPast on the first call, so one such
        // call is sufficient to set pastBlockTime to the current block.timestamp,
        // and on all subsequent calls of this setup branch block.timestamp is
        // unchanged and strictly greater than the new oldPast (also equal to
        // block.timestamp), so the fallback will not revert and will overwrite
        // pastBlockTime with the same block.timestamp again.
        if (targetTimestamp <= oldPast) {
            c.fallback{value: 10 ether}();
            oldPast = c.pastBlockTime();
            c.fallback{value: 10 ether}();
            oldPast = c.pastBlockTime();
        }

        bool reverted;
        try c.fallback{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint newPast = c.pastBlockTime();

        if (amount == 10 ether && targetTimestamp > oldPast) {
            assert(!reverted && newPast > oldPast);
        } else {
            assert(reverted && newPast == oldPast);
        }
    }

    receive() external payable {}
}

