contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 ts) public payable {
        require(address(this).balance >= 10 ether);

        // Read the initial public state (getter is safe).
        uint256 before = c.pastBlockTime();

        // Ensure the timestamp is strictly later than the current stored time.
        require(ts > before);

        // Move the contract to the desired block timestamp, then make the
        // fallback call with exactly 10 ether.
        // (A fresh C has pastBlockTime == 0, so any ts > 0 sets up a
        // valid timestamp; ts == 0 would be rejected by the precondition.)
        // We cannot call vm.warp; instead we choose a timestamp that is
        // already > before and rely on block.timestamp being at least that.
        // To make this deterministic for the checker, we simply use the
        // current block.timestamp and require the parameter to be later.
        // For the general property, we only need that the call succeeds
        // when the timestamp check passes.
        //
        // Since we cannot control block.timestamp, we adjust: use a ts that
        // is guaranteed to be > before by requiring ts > before, and check
        // the actual call behavior at the real block.timestamp.
        //
        // The rule: if the real block.timestamp > before, the call must
        // succeed (reverted == false). If not, it must revert.
        //
        // We cannot force block.timestamp, but we can read it indirectly by
        // attempting the call and observing the revert.

        bool reverted;
        try c.fallback{value: 10 ether}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // The deciding condition is whether block.timestamp > pastBlockTime.
        // We express this via the revert flag and the state change.
        // If the call succeeded, pastBlockTime must have advanced to
        // block.timestamp (which we don't know) but we can check that it
        // increased.
        // If the call reverted, pastBlockTime must remain unchanged.
        uint256 afterTs = c.pastBlockTime();

        if (!reverted) {
            assert(afterTs > before);
        } else {
            assert(afterTs == before);
        }
    }

    receive() external payable {}
}

