        // increasing block.timestamp. Since the setup set pastBlockTime to newTimestamp,
        // the second call at the same timestamp must revert and must not update state.
        assert(secondSuccess == false && storedAfterSecond == newTimestamp);
    }

    receive() external payable {}
}

